import Database from "better-sqlite3";
import path from "path";
import fs from "fs";

const DB_PATH = path.resolve("/home/user/qwik-app/metadata.db");

let db: Database.Database | null = null;

export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH);
    db.pragma("journal_mode = WAL");
    db.exec(`
      CREATE TABLE IF NOT EXISTS files (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        size INTEGER NOT NULL,
        mime TEXT NOT NULL,
        tag TEXT NOT NULL
      )
    `);
  }
  return db;
}

export interface FileRecord {
  id: number;
  name: string;
  size: number;
  mime: string;
  tag: string;
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { getDb } from "../../db";
import fs from "fs";
import path from "path";

const UPLOADS_DIR = path.resolve("/home/user/qwik-app/public/uploads");

export const onPost: RequestHandler = async ({ request, json }) => {
  try {
    const contentType = request.headers.get("content-type") || "";
    if (!contentType.includes("multipart/form-data")) {
      json(400, { error: "Content-Type must be multipart/form-data" });
      return;
    }

    const formData = await request.formData();
    const file = formData.get("file") as File | null;
    const tag = formData.get("tag") as string | null;

    if (!file || !(file instanceof File) || file.size === 0) {
      json(400, { error: "File is missing or invalid" });
      return;
    }

    if (!tag || typeof tag !== "string" || tag.trim() === "") {
      json(400, { error: "Tag is missing or invalid" });
      return;
    }

    // Ensure uploads directory exists
    if (!fs.existsSync(UPLOADS_DIR)) {
      fs.mkdirSync(UPLOADS_DIR, { recursive: true });
    }

    const buffer = Buffer.from(await file.arrayBuffer());
    const fileName = file.name;
    const filePath = path.join(UPLOADS_DIR, fileName);

    // Handle duplicate filenames by appending a timestamp
    let uniqueName = fileName;
    let uniquePath = filePath;
    if (fs.existsSync(filePath)) {
      const ext = path.extname(fileName);
      const base = path.basename(fileName, ext);
      uniqueName = `${base}_${Date.now()}${ext}`;
      uniquePath = path.join(UPLOADS_DIR, uniqueName);
    }

    fs.writeFileSync(uniquePath, buffer);

    const db = getDb();
    const stmt = db.prepare(
      "INSERT INTO files (name, size, mime, tag) VALUES (?, ?, ?, ?)"
    );
    const result = stmt.run(uniqueName, file.size, file.type || "application/octet-stream", tag.trim());

    json(201, {
      id: result.lastInsertRowid as number,
      name: uniqueName,
      size: file.size,
      mime: file.type || "application/octet-stream",
      tag: tag.trim(),
    });
  } catch (err: any) {
    json(400, { error: err.message || "Upload failed" });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { getDb } from "../../db";

export const onGet: RequestHandler = async ({ json }) => {
  const db = getDb();
  const rows = db.prepare("SELECT * FROM files").all();
  json(200, rows);
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { getDb } from "../../db";
import fs from "fs";
import path from "path";

const UPLOADS_DIR = path.resolve("/home/user/qwik-app/public/uploads");

export const onDelete: RequestHandler = async ({ params, json }) => {
  const id = parseInt(params.id, 10);

  if (isNaN(id)) {
    json(404, { error: "Invalid file ID" });
    return;
  }

  const db = getDb();
  const row = db.prepare("SELECT * FROM files WHERE id = ?").get(id) as any;

  if (!row) {
    json(404, { error: "File not found" });
    return;
  }

  // Delete physical file from disk if it exists
  const filePath = path.join(UPLOADS_DIR, row.name);
  if (fs.existsSync(filePath)) {
    fs.unlinkSync(filePath);
  }

  // Delete database record
  db.prepare("DELETE FROM files WHERE id = ?").run(id);

  json(200, { success: true });
};

import { component$, useSignal, useVisibleTask$ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";

interface FileRecord {
  id: number;
  name: string;
  size: number;
  mime: string;
  tag: string;
}

export default component$(() => {
  const files = useSignal<FileRecord[]>([]);
  const message = useSignal("");
  const error = useSignal("");

  useVisibleTask$(async () => {
    await loadFiles();
  });

  async function loadFiles() {
    try {
      const res = await fetch("/files/list");
      if (res.ok) {
        const data = await res.json();
        files.value = data;
      }
    } catch (err: any) {
      error.value = "Failed to load files";
    }
  }

  async function handleUpload(e: Event) {
    e.preventDefault();
    message.value = "";
    error.value = "";

    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);

    try {
      const res = await fetch("/files/upload", {
        method: "POST",
        body: formData,
      });

      if (res.ok) {
        message.value = "File uploaded successfully!";
        form.reset();
        await loadFiles();
      } else {
        const data = await res.json();
        error.value = data.error || "Upload failed";
      }
    } catch (err: any) {
      error.value = "Upload failed";
    }
  }

  async function handleDelete(id: number) {
    message.value = "";
    error.value = "";

    try {
      const res = await fetch(`/files/${id}`, {
        method: "DELETE",
      });

      if (res.ok) {
        message.value = "File deleted successfully!";
        await loadFiles();
      } else {
        const data = await res.json();
        error.value = data.error || "Delete failed";
      }
    } catch (err: any) {
      error.value = "Delete failed";
    }
  }

  function formatSize(bytes: number): string {
    if (bytes < 1024) return bytes + " B";
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
    return (bytes / (1024 * 1024)).toFixed(1) + " MB";
  }

  return (
    <div>
      <h1>File Explorer</h1>

      {message.value && (
        <div style={{ color: "green", marginBottom: "10px" }}>{message.value}</div>
      )}
      {error.value && (
        <div style={{ color: "red", marginBottom: "10px" }}>{error.value}</div>
      )}

      <form id="upload-form" preventdefault:submit onSubmit$={handleUpload}>
        <div style={{ marginBottom: "10px" }}>
          <label>
            File:{" "}
            <input id="file-input" name="file" type="file" />
          </label>
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label>
            Tag:{" "}
            <input id="tag-input" name="tag" type="text" placeholder="e.g. documents, images" />
          </label>
        </div>
        <button type="submit">Upload</button>
      </form>

      <hr style={{ margin: "20px 0" }} />

      <h2>Uploaded Files</h2>
      <div id="file-list">
        {files.value.length === 0 && <p>No files uploaded yet.</p>}
        {files.value.map((file) => (
          <div
            key={file.id}
            style={{
              border: "1px solid #ccc",
              padding: "10px",
              marginBottom: "10px",
              borderRadius: "4px",
            }}
          >
            <div>
              <strong>{file.name}</strong>
            </div>
            <div>Size: {formatSize(file.size)}</div>
            <div>MIME: {file.mime}</div>
            <div>Tag: {file.tag}</div>
            <button
              class="delete-btn"
              data-id={file.id}
              style={{ marginTop: "8px", color: "white", backgroundColor: "#e53e3e", border: "none", padding: "6px 12px", borderRadius: "4px", cursor: "pointer" }}
              onClick$={() => handleDelete(file.id)}
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
});

export const head: DocumentHead = {
  title: "File Explorer",
};

